    "meaning": "Nachsilbe -tou: Dinge (Stein, Holz), Ortswörter (drinnen, draußen), abstrakte Nomen (Gedanke, Vorteil)",
    "formation": "Nomen-, Verb- oder Adjektivstamm + 头 (tonlos: -tou) → Nomen",
    "notes": "Im Norden hört man oft die Form mit Erhua (-tour). Verb + 头 heißt auch „etwas, das sich lohnt“: 这部电影没什么看头 „dieser Film lohnt sich kaum“ – die Muster mit 有什么 (yǒu shénme) bzw. 没什么 (méi shénme) + Verb + 头儿 (tóur) sind eigene Punkte (HSK 7–9).",
    "explanation": "头 (tóu) „Kopf“ dient als Nachsilbe -头 zur Bildung von Nomen; dabei wird es meist tonlos gesprochen (-tou). Drei Gruppen sind wichtig:\n(1) Konkrete Dinge: 石头 (shítou) „Stein“, 木头 (mùtou) „Holz“, 骨头 (gǔtou) „Knochen“, 舌头 (shétou) „Zunge“, 馒头 (mántou) „gedämpftes Brötchen“.\n(2) Ortswörter: 里头 (lǐtou) „drinnen“, 外头 (wàitou) „draußen“, 上头 (shàngtou) „oben“, 前头 (qiántou) „vorn“, 后头 (hòutou) „hinten“ – umgangssprachlich und gleichbedeutend mit 里边 (lǐbian), 外面 (wàimiàn) usw.\n(3) Abstrakte Nomen aus Verben oder Adjektiven: 念头 (niàntou) „Gedanke, Einfall“, 甜头 (tiántou) „Vorteil, Nutzen“, 苦头 (kǔtou) „Leid, bittere Erfahrung“, 看头 (kàntou) „etwas Sehenswertes“.\nNicht jedes 头 ist Nachsilbe: In 头发 (tóufa) „Haare“ oder 点头 (diǎn tóu) „nicken“ hat es seine volle Bedeutung und seinen Ton, in 一头牛 (yì tóu niú) ist es Zählwort.",
