    "meaning": "Hinweisende Pronomen: einander, so/derart, dieser/unser (formell)",
    "formation": "彼此 + Verb · 如此 + Adjektiv/Verb · 本 + Nomen/Zählwort",
    "notes": "彼此 (bǐcǐ) vs. 互相 (hùxiāng): 互相 ist ein Adverb und steht nur vor Verben; 彼此 kann auch Objekt oder Attribut sein: 彼此的关系 (bǐcǐ de guānxi) „die gegenseitige Beziehung“. 如此 (rúcǐ) steckt in festen Wendungen wie 不仅如此 (bùjǐn rúcǐ) „nicht nur das“ und 尽管如此 (jǐnguǎn rúcǐ) „trotzdem“. 本 ist außerdem Zählwort für Bücher (一本书).",
    "explanation": "Drei schriftsprachlich geprägte Pronomen, die man vor allem in Texten, Ansagen und formellen Gesprächen hört.\n彼此 (bǐcǐ) – „einander, gegenseitig; beide Seiten“: 彼此帮助 (bǐcǐ bāngzhù) „einander helfen“; auch als Nomen: 不分彼此 (bù fēn bǐcǐ) „nicht zwischen Mein und Dein unterscheiden“. Die Antwort 彼此彼此 (bǐcǐ bǐcǐ) heißt höflich „gleichfalls, ganz meinerseits“.\n如此 (rúcǐ) – „so, derart“, schriftlich für 这么 (zhème) oder 这样 (zhèyàng): 如此美丽 (rúcǐ měilì) „so schön“; auch als Prädikat: 事实如此 (shìshí rúcǐ) „so ist es nun einmal“.\n本 (běn) – „dieser, der vorliegende; unser eigener“, direkt vor Nomen oder Zählwörtern, wenn sich Sprecher, Firma oder Text auf sich selbst beziehen: 本公司 (běn gōngsī) „unsere Firma“, 本次列车 (běn cì lièchē) „dieser Zug“, 本月 (běn yuè) „dieser Monat“, 本人 (běnrén) „ich selbst; die betreffende Person“.",
