    "meaning": "Zählwörter u. a. für Bände, Blüten, Jahrgänge, Pferde, Zeilen, Flugzeuge, Gruppen, Sträuße, Folgen, Wochen",
    "formation": "Zahl/这/那 + Zählwort + Nomen",
    "notes": "支 vs. 根: 支 eher für harte, gerade Gegenstände (Stifte), 根 für alles Lange, Dünne, auch Weiches (Haare, Seile); bei Zigaretten sind beide üblich. Als Zählwort wird 行 háng gesprochen, nicht xíng. 周 kann auch Runden zählen: 绕操场跑三周 (rào cāochǎng pǎo sān zhōu) „drei Runden um den Sportplatz laufen“.",
    "explanation": "Fünfzehn weitere Zählwörter; sie stehen wie alle zwischen Zahl (bzw. 这/那) und Nomen.\n册 (cè) – Bände, Exemplare: 全书共五册 (quán shū gòng wǔ cè) „das Werk hat fünf Bände“.\n朵 (duǒ) – Blüten, Wolken: 一朵花 (yì duǒ huā), 几朵白云 (jǐ duǒ báiyún).\n届 (jiè) – wiederkehrende Veranstaltungen, Amtszeiten, Abschlussjahrgänge: 第十届运动会 (dì shí jiè yùndònghuì) „die zehnten Sportspiele“.\n颗 (kē) – kleine runde Dinge: 一颗星星 (yì kē xīngxing), 一颗牙 (yì kē yá), 一颗心 (yì kē xīn).\n匹 (pǐ) – Pferde: 一匹马 (yì pǐ mǎ).\n行 (háng) – Zeilen, Reihen: 两行字 (liǎng háng zì) „zwei Zeilen“.\n架 (jià) – Flugzeuge, Geräte mit Gestell: 一架飞机 (yí jià fēijī), 一架钢琴 (yí jià gāngqín).\n群 (qún) – Gruppen, Scharen, Herden: 一群学生 (yì qún xuésheng), 一群羊 (yì qún yáng).\n支 (zhī) – harte, längliche Dinge; auch Lieder und Teams: 一支笔 (yì zhī bǐ), 一支球队 (yì zhī qiúduì).\n根 (gēn) – lange, dünne Dinge: 两根筷子 (liǎng gēn kuàizi), 一根头发 (yì gēn tóufa).\n批 (pī) – Lieferungen, Gruppen, die zusammen ankommen: 一批货 (yì pī huò).\n束 (shù) – Bündel, Sträuße: 一束花 (yí shù huā), 一束光 (yí shù guāng) „ein Lichtstrahl“.\n副 (fù) – Paare, Sets; Gesichtsausdrücke: 一副眼镜 (yí fù yǎnjìng) „eine Brille“, 一副手套 (yí fù shǒutào).\n集 (jí) – Folgen einer Serie: 第三集 (dì sān jí) „Folge drei“.\n周 (zhōu) – Wochen, direkt nach der Zahl: 两周 (liǎng zhōu) „zwei Wochen“.",
