        "chinese": "他回头看了我一眼，什么也没说。",
        "pinyin": "Tā huítóu kàn le wǒ yì yǎn, shénme yě méi shuō.",
        "german": "Er drehte sich um, warf mir einen Blick zu und sagte nichts."
