    "meaning": "Gradadverbien: allzu, ziemlich, verhältnismäßig, echt (umgangssprachlich), besonders, äußerst",
    "formation": "过于/相当/较/可/格外/极其 + Adjektiv/Verb",
    "notes": "较 als Präposition „verglichen mit“ (较²) ist ein eigener Punkt (HSK 5). 可 hat weitere Gebrauchsweisen: 可¹ „aber“ als Konjunktion (HSK 3) und 可³ als betonendes Modaladverb (HSK 5). 过于 (guòyú) ist wie 太 meist negativ gefärbt, 格外 (géwài) und 相当 (xiāngdāng) sind neutral bis positiv.",
    "explanation": "Diese Gradadverbien stehen vor Adjektiven oder Gefühlsverben; die meisten sind eher schriftsprachlich, nur 可 ist typisch für die Umgangssprache.\n过于 (guòyú) – „allzu, übermäßig“; kritisiert ein Zuviel, meist vor zweisilbigen Wörtern: 过于紧张 (guòyú jǐnzhāng) „übermäßig nervös“. Formeller als 太 (tài).\n相当 (xiāngdāng) – „ziemlich, recht, beachtlich“; stärker als 比较 (bǐjiào), schwächer als 非常 (fēicháng): 相当不错 (xiāngdāng búcuò) „ziemlich gut“.\n较¹ (jiào) – „verhältnismäßig, relativ“; schriftliche Kurzform von 比较, meist vor einsilbigen Adjektiven: 较大 (jiào dà), 较少 (jiào shǎo).\n可² (kě) – „echt, aber so was von“; emotional und umgangssprachlich, meist mit 了 oder 呢 am Satzende: 今天可冷了 (jīntiān kě lěng le) „heute ist es echt kalt“.\n格外 (géwài) – „besonders, ungewöhnlich“; stärker als sonst oder als erwartet: 格外高兴 (géwài gāoxìng).\n极其 (jíqí) – „äußerst, höchst“; schriftsprachlich, vor zweisilbigen Wörtern: 极其重要 (jíqí zhòngyào).",
