    "notes": "In Aufforderungen und Plänen („komm öfter vorbei“) stehen 常 oder 常常 (chángcháng), nicht 通常 (tōngcháng). 通常 vs. 往往 (wǎngwǎng): 往往 fasst eine Erfahrung unter bestimmten Umständen zusammen („wenn …, dann oft“), 通常 nennt einfach den Normalfall.",
    "explanation": "Drei Adverbien geben an, wie oft etwas geschieht.\n老是 (lǎoshì) – „immer wieder, ständig“; umgangssprachlich und meist unzufrieden oder klagend: 你怎么老是迟到 (nǐ zěnme lǎoshì chídào) „Warum kommst du ständig zu spät?“ Bedeutet dasselbe wie 总是 (zǒngshì), ist aber stärker negativ gefärbt.\n通常 (tōngcháng) – „normalerweise, in der Regel“; beschreibt eine Regelmäßigkeit oder Gewohnheit und kann auch vor dem Subjekt stehen: 通常我七点起床 (tōngcháng wǒ qī diǎn qǐchuáng) „normalerweise stehe ich um sieben auf“. Auch als Attribut: 通常情况下 (tōngcháng qíngkuàng xià) „unter normalen Umständen“.\n时常 (shícháng) – „oft, häufig“; etwas schriftlicher als 常常 (chángcháng) oder 经常 (jīngcháng).",
