    "explanation": "Modaladverbien zeigen die Haltung des Sprechers (Begründung, Überraschung, Nachdruck); sie stehen meist nach dem Subjekt vor dem Prädikat, einige auch am Satzanfang.\n毕竟 (bìjìng) – „schließlich, immerhin“; nennt eine Tatsache, die man bedenken sollte.\n居然 (jūrán) – „wider Erwarten, doch tatsächlich“; Überraschung, wie 竟然 (jìngrán).\n反正 (fǎnzhèng) – „sowieso, jedenfalls“; das Ergebnis bleibt unter allen Umständen gleich.\n根本 (gēnběn) – „überhaupt (nicht), ganz und gar (nicht)“; meist mit Verneinung: 根本不知道 (gēnběn bù zhīdào).\n果然 (guǒrán) – „wie erwartet, tatsächlich“; bestätigt eine Vorhersage.\n简直 (jiǎnzhí) – „geradezu, schlichtweg“; bewusste Übertreibung: 简直像做梦一样 (jiǎnzhí xiàng zuò mèng yíyàng) „wie im Traum“.\n绝对 (juéduì) – „absolut, garantiert“: 绝对没问题 (juéduì méi wèntí).\n的确 (díquè) – „wirklich, in der Tat“; bestätigt eine Aussage, wie 确实 (quèshí).\n反而 (fǎn'ér) – „im Gegenteil, stattdessen“; das Ergebnis widerspricht der Erwartung.\n白 (bái) – „umsonst, vergeblich“: 白跑一趟 (bái pǎo yí tàng) „den Weg umsonst machen“; auch „gratis“.\n刚好 (gānghǎo) – „gerade richtig; zufällig gerade“: 刚好赶上 (gānghǎo gǎnshàng) „es gerade noch schaffen“.\n可³ (kě) – betont eine Aussage gefühlsbetont: 你可来了 (nǐ kě lái le) „endlich bist du da!“, 可别忘了 (kě bié wàng le) „vergiss es bloß nicht!“.",
