    "formation": "Ursache/Erwartung，(Subjekt +) 反而 + gegenteiliges Ergebnis",
    "explanation": "反而 (fǎn'ér) zeigt, dass ein erwartetes Ergebnis nicht nur ausbleibt, sondern sogar das Gegenteil eintritt: „im Gegenteil, stattdessen, eher noch“. Der erste Teil nennt den Umstand, der eigentlich etwas anderes erwarten ließ (Medizin genommen → sollte besser werden), der zweite Teil mit 反而 das gegenteilige Ergebnis. 反而 steht nach dem Subjekt vor dem Prädikat; oft folgt eine Steigerung mit 更 (gèng). Typisch ist auch der Rahmen 不但不/没……，反而…… „nicht nur nicht …, sondern im Gegenteil …“. Ein häufiger Fehler ist, 反而 als einfaches „aber“ zu verwenden, wenn gar keine Erwartung umgekehrt wird – dafür stehen 但是 (dànshì) oder 却 (què).",
    "notes": "反而 (fǎn'ér) vs. 却 (què): 却 drückt jeden Gegensatz aus („aber, doch“), 反而 nur das Gegenteil des Erwarteten. Der Rahmen mit 不但不 (búdàn bù) bzw. 不但没有 (búdàn méiyǒu) … 反而 … ist ein eigener Punkt (HSK 5); 不但 (búdàn) … 而且 (érqiě) steigert dagegen in dieselbe Richtung.",
