    "explanation": "毕竟 (bìjìng) verweist auf eine grundlegende Tatsache, die man bei einer Beurteilung bedenken sollte: „schließlich, immerhin, letzten Endes“. Damit relativiert man eine Kritik, rechtfertigt ein Verhalten oder erklärt etwas: 他毕竟还是个孩子 „er ist schließlich noch ein Kind“. Der andere Teilsatz zieht daraus die Schlussfolgerung (别怪他 „sei ihm nicht böse“). Oft folgt 是 oder 还是 (háishi). 毕竟 kann nach dem Subjekt oder am Satzanfang stehen. In Fragen wird es nicht gebraucht – „was denn eigentlich?“ heißt 到底 (dàodǐ) oder 究竟 (jiūjìng).",
