    "formation": "Vorhersage/Vermutung，(Subjekt +) 果然 + Ergebnis",
    "explanation": "果然 (guǒrán) bestätigt, dass etwas so eingetreten ist, wie man es vorhergesagt, vermutet oder gehört hat: „wie erwartet, tatsächlich, wirklich“. Meist nennt der Satz zuerst die Erwartung, etwa mit 听说 (tīngshuō) „ich habe gehört“ oder 天气预报说 (tiānqì yùbào shuō) „laut Wetterbericht“, dann folgt 果然 mit dem Ergebnis. 果然 steht vor dem Prädikat, kann aber auch vor dem Subjekt stehen: 果然，他又迟到了 „und prompt kam er wieder zu spät“. Ein typischer Fehler ist die Verwechslung mit 居然 (jūrán) oder 竟然 (jìngrán), die das Gegenteil ausdrücken: Überraschung über etwas Unerwartetes. Fast gleichbedeutend ist 果真 (guǒzhēn).",
    "notes": "果然 (guǒrán) „wie erwartet“ vs. 居然 (jūrán)/竟然 (jìngrán) „wider Erwarten“. Feste Wendung: 果然不出所料 (guǒrán bù chū suǒ liào) „genau wie vorhergesehen“.",
