    "explanation": "反正 (fǎnzhèng) betont, dass ein Ergebnis oder eine Haltung unter allen Umständen gleich bleibt. Zwei Gebrauchsweisen sind typisch: (1) Es nennt einen Umstand, der ohnehin gilt und deshalb eine Entscheidung begründet: „sowieso, ohnehin“ – 反正时间还早，我们慢慢走吧 „es ist ja sowieso noch früh, lass uns gemütlich gehen“. (2) Nach 不管 (bùguǎn), 无论 (wúlùn) oder einer Aufzählung von Möglichkeiten bedeutet es „jedenfalls, egal wie“: 不管你去不去，反正我要去 „ob du gehst oder nicht – ich gehe jedenfalls“. 反正 steht oft am Anfang des Teilsatzes vor dem Subjekt, kann aber auch nach dem Subjekt stehen. Es ist typisch für die gesprochene Sprache und kann entschlossen oder auch gleichgültig klingen.",
