    "notes": "Feste Wörter mit 沿: 沿海 (yánhǎi) „Küstengebiet“, 沿途 (yántú) „unterwegs, entlang der Strecke“. 顺着 (shùnzhe) „entlang, folgend“ ist im Gespräch fast gleichbedeutend. 从² (cóng) nennt einen Weg, durch den oder an dem vorbei man geht (从这儿过), nicht eine Linie, der man folgt.",
    "explanation": "沿 (yán) bzw. 沿着 (yánzhe) nennt den Weg, die Linie oder Grenze, der eine Bewegung folgt: „entlang, an … entlang“. Die Gruppe steht vor dem Verb oder am Satzanfang: 沿着河边散步 „am Fluss entlang spazieren“, 沿着这条路一直走 „diese Straße immer entlang gehen“. 沿着 ist die übliche Form im Gespräch und vor längeren Nomengruppen; das bloße 沿 klingt knapper und schriftlicher und steht gern vor einsilbigen Nomen, etwa 沿河 (yán hé) oder 沿街 (yán jiē). Übertragen bezeichnet 沿着 auch einen eingeschlagenen Weg: 沿着正确的方向前进 (yánzhe zhèngquè de fāngxiàng qiánjìn) „in die richtige Richtung weitergehen“. Im Unterschied zu 朝 (cháo) und 往 (wǎng), die nur eine Richtung angeben, beschreibt 沿（着） den ganzen Weg, auf dem man sich bewegt.",
