    "notes": "同² (tóng) als Konjunktion „und“ (我同他都去) ist ein eigener HSK-5-Punkt. 较 als Adverb (较¹) heißt „relativ, ziemlich“: 较好 (jiàohǎo) „relativ gut“. 替 ist auch Verb „ersetzen, vertreten“: 我替你 „ich übernehme für dich“.",
    "explanation": "Diese Präpositionen führen die Person oder Sache ein, auf die sich eine Handlung oder ein Vergleich bezieht; die Gruppe steht vor dem Verb.\n替 (tì) – „für, anstelle von“: man tut etwas stellvertretend oder zugunsten von jemandem: 替我向他问好 „grüß ihn von mir“, 同事替我上班 „ein Kollege arbeitet für mich“. Gesprochen wie geschrieben üblich.\n同¹ (tóng) – „mit“: nennt den Partner einer Handlung wie 跟 (gēn) und 和 (hé): 同他商量 „mit ihm besprechen“. Klingt etwas gehobener bzw. regional (Süden).\n较² (jiào) – „im Vergleich zu, gegenüber“: schriftsprachliches Gegenstück zu 比 (bǐ), v. a. in Berichten und Statistiken: 今年较去年有所增加 „gegenüber dem Vorjahr gestiegen“.",
