    "formation": "凭 + Grundlage/Mittel (+ Subjekt) + Verb",
    "notes": "靠 (kào) „sich verlassen auf“ ist im Gespräch oft austauschbar (靠自己的努力). 据 (jù) und 依据 (yījù) nennen eine Informationsquelle bzw. eine Vorschrift; 凭 eher persönliche Mittel oder Belege. Als Verb heißt 凭 „sich stützen auf“: 凭的是实力 „es zählt das Können“.",
    "explanation": "Die Präposition 凭 (píng) nennt, worauf sich jemand stützt, um etwas zu erreichen oder zu tun: eine Fähigkeit, Erfahrung, ein Beweisstück oder ein Dokument – „aufgrund von, kraft, mit“. 凭自己的努力 „aus eigener Kraft“, 凭经验 „aus Erfahrung“, 凭票入场 (píng piào rùchǎng) „Einlass nur mit Eintrittskarte“. Die Gruppe steht vor dem Verb oder, durch Komma abgetrennt, am Satzanfang. Die vorwurfsvolle Frage 凭什么 (píng shénme) bedeutet „mit welchem Recht?“ und klingt schroff. Anders als 根据 (gēnjù), das eine Grundlage für ein Urteil oder eine Information nennt, betont 凭 das Mittel, mit dem man etwas schafft oder sich ausweist.",
