    "formation": "据 + Quelle/Verb des Erfahrens (说/报道/调查/了解)，Information",
    "notes": "据我所知 (jù wǒ suǒ zhī) „soweit ich weiß“ ist ein eigener Zusatzpunkt. 凭 (píng) nennt das Mittel einer Handlung (凭票入场 (píng piào rùchǎng)), nicht eine Informationsquelle. Das Nomen 证据 (zhèngjù) „Beweis“ enthält dasselbe Zeichen.",
    "explanation": "Die Präposition 据 (jù) nennt die Quelle, auf die sich eine Information stützt: „laut, nach, zufolge“. Sie steht fast immer am Satzanfang, gefolgt von einem Komma, und verbindet sich gern mit Verben des Mitteilens oder Erfahrens: 据报道 (jù bàodào) „Berichten zufolge“, 据调查 (jù diàochá) „laut einer Umfrage“, 据统计 (jù tǒngjì) „laut Statistik“, 据了解 (jù liǎojiě) „wie zu erfahren ist“, 据他说 „nach seinen Worten“. Häufig ist das feste Wort 据说 (jùshuō) „angeblich, es heißt“, wenn die Quelle offen bleibt. 据 klingt knapper und schriftlicher als 根据 (gēnjù); in Nachrichten und Berichten ist es sehr häufig. Vor einem bloßen Nomen ohne Verb steht meist 根据 (根据天气预报).",
