    "explanation": "总之 (zǒngzhī) leitet eine Zusammenfassung oder ein Fazit ein: „kurzum, kurz gesagt, alles in allem“. Es steht am Anfang des letzten Satzes oder Teilsatzes, oft nach einer Aufzählung von Einzelheiten, und wird meist durch Komma abgetrennt. Ein zweiter Gebrauch: Nach etwas Unklarem oder Unentschiedenem hält 总之 fest, was trotzdem feststeht – „jedenfalls, wie auch immer“: 我也不知道为什么，总之他不来了. Hier steht oft 不管 (bùguǎn) oder 反正 (fǎnzhèng) in der Nähe. 总之 ist in Rede wie Schrift üblich; formeller sind 总而言之 (zǒng'éryánzhī) und 总的来说 (zǒng de lái shuō).",
    "notes": "反正 (fǎnzhèng) „sowieso, ohnehin“ betont, dass etwas unter allen Umständen gilt, und steht oft mitten im Satz; 总之 (zǒngzhī) schließt zusammenfassend ab. 简而言之 (jiǎn'éryánzhī) „kurz gesagt“ ist ein HSK-7–9-Punkt.",
