    "meaning": "dadurch, somit, und so (Ergebnis einer Handlung)",
    "formation": "Handlung/Ursache，从而 + (beabsichtigtes) Ergebnis",
    "explanation": "从而 (cóng'ér) leitet im zweiten Teilsatz das Ergebnis ein, das aus einer vorher genannten Handlung oder Maßnahme folgt: „dadurch, somit, und so“. Beide Teile haben in der Regel dasselbe Subjekt, das im zweiten Teil nicht wiederholt wird: 公司调整了策略，从而提高了竞争力. Das Ergebnis ist meist erwünscht oder beabsichtigt (提高 (tígāo), 减少 (jiǎnshǎo), 改善 (gǎishàn)); für unerwünschte Folgen steht eher 以致 (yǐzhì). 从而 gehört zur Schriftsprache und zu formellen Reden, etwa in Berichten und Aufsätzen; im Alltag sagt man 所以 (suǒyǐ) oder 这样 (zhèyàng) „so“. Anders als 因此 (yīncǐ) betont 从而 weniger den Grund als den Weg, über den das Ergebnis erreicht wird.",
    "notes": "因此 (yīncǐ) und 因而 (yīn'ér) nennen allgemein eine Folge („deshalb“); 以至（于） (yǐzhì(yú)) „sodass“ betont das Ausmaß, 以致 (yǐzhì) eine meist negative Folge.",
    "examples": [
      {
        "chinese": "政府采取了新措施，从而减少了空气污染。",
        "pinyin": "Zhèngfǔ cǎiqǔ le xīn cuòshī, cóng'ér jiǎnshǎo le kōngqì wūrǎn.",
        "german": "Die Regierung hat neue Maßnahmen ergriffen und dadurch die Luftverschmutzung verringert."
      },
      {
        "chinese": "他每天坚持练习，从而大大提高了口语水平。",
        "pinyin": "Tā měi tiān jiānchí liànxí, cóng'ér dàdà tígāo le kǒuyǔ shuǐpíng.",
        "german": "Er hat jeden Tag beharrlich geübt und so sein mündliches Niveau stark verbessert."
      },
      {
        "chinese": "公司调整了策略，从而提高了竞争力。",
        "pinyin": "Gōngsī tiáozhěng le cèlüè, cóng'ér tígāo le jìngzhēnglì.",
        "german": "Das Unternehmen passte seine Strategie an und steigerte dadurch seine Wettbewerbsfähigkeit."
      }
    ],
