    "notes": "像……一样 (yíyàng) ist gleichbedeutend und in allen Registern üblich; 像……一般 (yìbān) klingt literarisch. Man findet auch die Schreibung 是的 (shìde) – korrekt ist 似的 (shìde). 似乎 (sìhū) „anscheinend“ ist ein Adverb vor dem Verb, keine Partikel am Ende.",
    "explanation": "Die Partikel 似的 (shìde) steht hinter einem Wort, einer Wortgruppe oder einem Satz und drückt Ähnlichkeit oder eine Vermutung aus: „wie, als ob“. Häufig steht davor 像 (xiàng), 好像 (hǎoxiàng) oder 仿佛 (fǎngfú): 像孩子似的 „wie ein Kind“, 好像什么都知道似的 „als wüsste er alles“. Die Gruppe mit 似的 kann Prädikat sein, als Attribut vor einem Nomen stehen (像花儿似的姑娘) oder als Adverbial vor dem Verb (飞似的跑了 „wie der Wind davonrennen“), auch als Komplement nach 得: 高兴得像个孩子似的. 似的 ist umgangssprachlich; neutraler ist 像……一样 (yíyàng). Achtung Aussprache: shìde, nicht sìde – anders als in 似乎 (sìhū).",
