    "formation": "Verb + 来 + dasselbe Verb + 去",
    "notes": "Das Muster X来X去 mit 都是 (dōu shì) bzw. 就是 (jiù shì) im Folgeteil (HSK 5) ist ein eigener Punkt: „wie man es auch dreht, es bleibt …“. A着A着 (HSK 5) beschreibt dagegen eine Handlung, in deren Verlauf plötzlich etwas Neues geschieht.",
    "explanation": "In A来A去 steht zweimal dasselbe (meist einsilbige) Verb, verbunden durch 来 und 去. Bei Bewegungsverben beschreibt das Muster eine Bewegung hin und her: 走来走去 „auf und ab gehen“, 飞来飞去 (fēi lái fēi qù) „hin und her fliegen“. Bei anderen Verben heißt es „immer wieder, lange“: 想来想去 „hin und her überlegen“, 找来找去 „überall suchen“, 说来说去 (shuō lái shuō qù) „wie man es auch dreht“. Oft folgt ein Teilsatz mit dem Ergebnis, das nach langem Hin und Her eintritt oder ausbleibt: 想来想去，还是决定不去了; 找来找去也没找到. Das Muster ist umgangssprachlich und anschaulich; die Reihenfolge 来 – 去 ist fest.",
