    "explanation": "没A没B verneint zwei zusammengehörende Begriffe und betont so ein völliges Fehlen. A und B sind einsilbige Wörter mit gegensätzlicher oder ähnlicher Bedeutung; das Muster bildet überwiegend feste Ausdrücke, die oft tadelnd gemeint sind: 没大没小 (méi dà méi xiǎo) „respektlos gegenüber Älteren“, 没完没了 (méi wán méi liǎo) „endlos, ohne Ende“, 没日没夜 (méi rì méi yè) „Tag und Nacht, rund um die Uhr“, 没头没脑 (méi tóu méi nǎo) „zusammenhanglos, unvermittelt“. Die Ausdrücke stehen als Prädikat (meist mit 的) oder als Adverbial mit 地 vor dem Verb. Freie Neubildungen sind selten; man lernt die Ausdrücke am besten als Einheiten.",
