    "notes": "在……看来 (kànlái), ein HSK-3-Punkt, nennt die Person, deren Meinung wiedergegeben wird (在我看来 (zài wǒ kànlái) „meiner Meinung nach“); 从……来看 nennt dagegen einen Gesichtspunkt oder Hinweis. 看来 allein heißt „anscheinend“. Nicht verwechseln mit 从……起/开始 (zeitlicher Beginn).",
    "explanation": "从……来看 (lái kàn) nennt den Blickwinkel oder den Anhaltspunkt, von dem aus man ein Urteil fällt: „von … aus betrachtet, nach … zu urteilen“. Zwischen 从 und 来看 steht ein Nomen wie 角度 (jiǎodù) „Blickwinkel“, 情况 (qíngkuàng) „Lage“ oder ein konkretes Indiz (他的表情 „sein Gesichtsausdruck“). Die Gruppe steht am Satzanfang, durch Komma vom Urteil getrennt, das oft eine Vermutung ist (可能 (kěnéng), 好像 (hǎoxiàng), 应该 (yīnggāi)). Gleichbedeutend sind die kürzeren Formen 从……看 und 从……上看 sowie 从……看来 (kànlái); 从……来说 (lái shuō) betont eher den Standpunkt als ein Indiz. Das Muster ist in Gespräch und Schrift üblich, besonders in Analysen und Kommentaren.",
