    "notes": "有的 (yǒude) …，有的 … „manche …, andere …“ sagt Ähnliches neutraler und lässt längere Ausdrücke zu. 一A一B (HSK 4) beschreibt dagegen ein abwechselndes oder paarweises Geschehen.",
    "explanation": "A的A，B的B beschreibt, dass sich eine Gruppe auf verschiedene Weise verhält oder in verschiedenen Zuständen ist: „die einen …, die anderen …“. Die Gruppe steht davor (大家 (dàjiā), 同学们, 村里的年轻人); A und B sind meist einsilbige Verben oder Adjektive, die jeweils wiederholt werden: 唱的唱，跳的跳 „die einen singen, die anderen tanzen“, 走的走，留的留 „die einen gehen, die anderen bleiben“. Das erste A的 bedeutet so viel wie „diejenigen, die A tun“. Oft steht danach eine Gesamtbewertung (非常热闹 „es ist sehr lebhaft“) oder eine Folge. Das Muster wirkt lebendig und ist typisch für Erzählungen; auch drei Glieder kommen vor. Typischer Fehler: 得 statt 的 schreiben.",
