    "formation": "（自/从）+ Zeitpunkt/Ereignis/Zeitraum + 以来，+ Entwicklung bis jetzt",
    "notes": "以后 (yǐhòu) heißt „nach, später“ und kann sich auch auf die Zukunft beziehen, 以来 (yǐlái) reicht immer bis zur Gegenwart. Feste Verbindungen: 自古以来 (zìgǔ yǐlái) „seit jeher“, 长期以来 (chángqī yǐlái) „seit langem“, 有史以来 (yǒushǐ yǐlái) „seit Menschengedenken“. Gesprochen sagt man oft 从……以后 oder 开始 (kāishǐ) statt 自……以来.",
    "explanation": "以来 (yǐlái) markiert einen Ausgangspunkt in der Vergangenheit und umfasst die ganze Zeit von dort bis zur Gegenwart (oder bis zum Bezugszeitpunkt): „seit …“. Davor steht ein Zeitpunkt (去年九月以来), ein Ereignis (来中国以来, 毕业以来) oder ein Zeitraum (三年以来 „seit drei Jahren“). 自 (zì) oder 从 (cóng) am Anfang verstärken den Ausgangspunkt; 自……以来 klingt schriftlich und formell, ohne 自 ist es neutral. Der Hauptsatz beschreibt einen Zustand oder eine Entwicklung, die bis jetzt andauert – oft mit 一直 (yìzhí), 已经 (yǐjīng), 都 oder 了. Typischer Fehler: 以来 für Zukünftiges oder für einen einmaligen, abgeschlossenen Vorgang zu benutzen; dafür steht 以后 (yǐhòu).",
