    "notes": "Verwandt ist X也不是，Y也不是 („was man auch tut, es ist falsch“): Dort geht es um Verlegenheit, hier eher darum, dass etwas verboten oder unmöglich ist. 不得了 (bùdéliǎo) „schrecklich, äußerst“ ist ein eigener Ausdruck und hat mit diesem 不得 (bù dé) nur die Form gemeinsam.",
    "explanation": "Das Muster beschreibt eine Lage, in der beide naheliegenden Möglichkeiten ausgeschlossen sind: „X darf man nicht, Y aber auch nicht“. Jedes Verb wird wiederholt; 不得 (bù dé) hinter dem Verb heißt „nicht dürfen, nicht können, nicht ratsam“ (vgl. Potentialkomplement Verb + 不得). X und Y sind meist einsilbige Verben, die ein Paar bilden (打 – 骂, 坐 – 躺, 说 – 瞒). Der Ausdruck ist gesprochen und drückt Hilflosigkeit oder Ärger aus, oft gefolgt von 真没办法 „da kann man nichts machen“.",
