    "explanation": "Mit „X是它，Y也是它“ sagt man, dass ein und dieselbe Sache zwei (meist gegensätzliche) Wirkungen oder Rollen hat: „Es ist das, was X bewirkt – und auch das, was Y bewirkt.“ 它 (tā) verweist auf die vorher genannte Sache, die oft als Thema am Satzanfang steht, etwa 手机 (shǒujī) „Handy“. X und Y sind meist mit 的 nominalisierte Ausdrücke (让我高兴的、让我难过的) oder kurze Verben (成也是它，败也是它). Der Ausdruck betont Ambivalenz und wirkt nachdenklich oder resümierend; er steht in gesprochener wie geschriebener Sprache. Bei Personen sagt man entsprechend 他/她: 成也是他，败也是他.",
