    "explanation": "不管怎样说 (bùguǎn zěnyàng shuō) wörtlich „egal, wie man es sagt“ schließt eine Abwägung ab und leitet zu dem über, was trotz allem gilt: „wie dem auch sei“, „jedenfalls“, „unterm Strich“. Es steht am Satzanfang oder nach einem einräumenden Teil mit 虽然 (suīrán) … 但 und wird durch Komma abgetrennt. Danach folgt ein Fazit, eine Bewertung oder ein Rat. Gesprochen sagt man meist 不管怎么说 (bùguǎn zěnme shuō), schriftlicher 无论如何 (wúlùn rúhé). Anders als im Konditionalsatz 不管 (bùguǎn)……，都…… braucht der Hauptsatz hier kein 都/也.",
