    "explanation": "真有你的 (zhēn yǒu nǐ de) ist ein gesprochener Ausruf, mit dem man auf etwas Überraschendes reagiert, das jemand getan hat. Je nach Lage und Tonfall ist er anerkennend („Respekt! Wie hast du das geschafft?“) oder vorwurfsvoll-ironisch („Typisch du! Das sieht dir ähnlich!“). Mit 他/她 spricht man über eine dritte Person. Der Ausruf steht meist am Satzende nach der Schilderung der Tat, oft mit Ausrufezeichen. Er gehört in vertraute Gespräche, nicht in förmliche Situationen.",
