    "explanation": "Wird ein Verb oder Adjektiv vor und nach 什么 (shénme) wiederholt, entsteht keine Frage, sondern ein Vorwurf oder eine Aufforderung aufzuhören: 急什么急 „Was drängelst du so?“, 哭什么哭 „Hör auf zu weinen!“, 吵什么吵 „Hört auf zu streiten!“. Der Sprecher findet die Handlung oder Gefühlsregung unnötig oder ärgerlich und begründet das oft im Folgesatz. X ist meist ein einsilbiges Verb oder Adjektiv; ein Objekt steht nicht dabei. Der Ausdruck ist gesprochen, emotional und wirkt barsch bis unhöflich (看什么看 „Was glotzt du?“) – unter Fremden vorsichtig verwenden.",
