    "explanation": "Mit 什么 (shénme) + X不X（的） wischt man ein Thema oder einen Einwand beiseite, den der andere gerade angesprochen hat: 什么贵不贵的 „ach, teuer oder nicht – egal“, 什么谢不谢的 „ach was, keine Ursache“. X kann ein Adjektiv (贵, 累), ein Verb (谢) oder ein Substantiv (钱) sein und wird mit 不 wiederholt; das 的 am Ende ist häufig, aber nicht nötig. Danach folgt, worauf es dem Sprecher eigentlich ankommt (你喜欢就买吧). Der Ausdruck ist gesprochen und klingt je nach Lage großzügig, beruhigend oder ungeduldig.",
