    "explanation": "„X来X去“ beschreibt ein wiederholtes, langes Hin und Her: 说来说去 (shuō lái shuō qù) „reden und reden“, 看来看去 „sich lange umsehen“, 想来想去 „hin und her überlegen“. Mit 都是 (dōu shì) oder 就是 (jiù shì) im zweiten Teil zieht man das Fazit: Trotz allem Hin und Her läuft es immer auf dasselbe hinaus. 就是 betont „im Grunde, eben nur“ (说来说去，就是不想帮忙); 都是 betont „alles, ausnahmslos“ (挑来挑去，都是我不爱吃的). Für X steht dasselbe, meist einsilbige Verb. Der Ausdruck ist gesprochen und klingt oft leicht enttäuscht oder ungeduldig.",
