    "notes": "Die Grundlagen (ein Adverbial aus Zeit, Ort oder Adverb) behandelt der HSK-1-Punkt zum 状语 (zhuàngyǔ). Bei 不 und 也/都 entscheidet die Stellung über die Reichweite: 都不 „alle nicht“, 不都 „nicht alle“.",
    "explanation": "Adverbiale stehen im Chinesischen vor dem Verb – anders als im Deutschen, wo Ort und Zeit oft dahinter kommen; was hinter dem Verb steht, ist ein Komplement. Treffen mehrere zusammen, gilt meist diese Reihenfolge: (1) Zeit, etwa 明天 (míngtiān) oder 昨天晚上 (zuótiān wǎnshang), die auch vor dem Subjekt stehen kann; (2) Satzadverbien, Häufigkeit und Verneinung, etwa 已经 (yǐjīng), 也, 都, 不, 再; (3) Modalverben (想, 要, 能); (4) Ausdrücke, die das Subjekt beschreiben, etwa 高高兴兴地 oder 一个人 (yí ge rén); (5) Ort (在图书馆, 从学校); (6) Bezugsperson oder Objekt mit Präposition (跟老师, 对他, 把书); (7) Art und Weise der Handlung (认真地, 慢慢地); dann das Verb. Die Reihenfolge ist eine starke Tendenz, keine starre Regel; Bedeutung und Betonung können sie verschieben. Typische Fehler: den Ort hinter das Verb stellen (falsch: 我吃饭在家) oder 不 an die falsche Stelle setzen – 我不在家吃饭 heißt „ich esse nicht zu Hause“, 我在家不吃饭 dagegen „zu Hause esse ich nichts“.",
