    "formation": "Verb/Adjektiv + 得 (dürfen/können) · Verb/Adjektiv + 不得 (nicht dürfen/nicht ratsam)",
    "notes": "Anders als bei 看得见 (kàn de jiàn) oder 看不见 (kàn bu jiàn) aus HSK 3 folgt hier kein Ergebnis- oder Richtungskomplement. 不了 (bu liǎo) betont eher das Nichtschaffen (吃不了 „nicht aufessen können“). Vor dem Verb ist 不得 (bùdé) ein schriftliches Verbot: 不得吸烟 „Rauchen verboten“. Lexikalisiert sind 舍不得 (shěbude), 恨不得 (hènbude), 怪不得 (guàibude) und 不得了 (bùdéliǎo) – eigene Wörter bzw. Punkte.",
    "explanation": "Hier ist 得 (dé) selbst das Potentialkomplement: „Verb + 得“ heißt „man darf/kann es tun“, „Verb + 不得 (bù dé)“ „man darf/sollte es nicht tun“. Gebräuchlich ist vor allem die verneinte Form: (1) Verbot oder Gefahr – 这种蘑菇吃不得 „die darf man nicht essen“; (2) nicht ratsam – 学外语急不得 „man darf nichts überstürzen“, 马虎不得 (mǎhu bu dé) „man darf nicht nachlässig sein“; (3) körperlich unmöglich – 他动不得 „er kann sich nicht rühren“. Die bejahte Form steht fast nur in Gegenüberstellungen oder Fragen (这个玩笑开得，那个开不得). Meist einsilbige Verben oder Adjektive wie 急, außerdem einige zweisilbige wie 马虎 (mǎhu). Der Ausdruck ist nachdrücklich und leicht idiomatisch; neutral sagt man 不能 (bù néng) + Verb.",
    "examples": [
      {
        "chinese": "这种蘑菇有毒，吃不得。",
        "pinyin": "Zhè zhǒng mógu yǒu dú, chī bu dé.",
        "german": "Diese Pilze sind giftig – die darf man nicht essen."
      },
      {
        "chinese": "学外语急不得，要一步一步来。",
        "pinyin": "Xué wàiyǔ jí bu dé, yào yí bù yí bù lái.",
        "german": "Beim Fremdsprachenlernen darf man nichts überstürzen, man muss Schritt für Schritt vorgehen."
      },
      {
        "chinese": "这件事关系到大家的安全，马虎不得。",
        "pinyin": "Zhè jiàn shì guānxi dào dàjiā de ānquán, mǎhu bu dé.",
        "german": "Hier geht es um die Sicherheit aller – da darf man nicht nachlässig sein."
      },
      {
        "chinese": "这个玩笑开得，那个玩笑可开不得。",
        "pinyin": "Zhège wánxiào kāi de, nàge wánxiào kě kāi bu dé.",
        "german": "Über das eine darf man Witze machen, über das andere auf keinen Fall."
      }
    ],
