    "explanation": "Die zusammengesetzten Richtungskomplemente beschreiben hier keinen Weg, sondern einen Zustand: 起来 (qǐlai) – ein Zustand beginnt und nimmt zu, meist von schwach zu stark: 热起来, 忙起来, 好起来 (hǎo qilai). 下来 (xiàlai) – Übergang von Bewegung in Ruhe, von stark zu schwach: 安静下来, 停下来 (tíng xialai), 天黑下来, 冷静下来. 下去 (xiàqu) – ein Zustand hält an und entwickelt sich weiter, oft negativ: 瘦下去, 冷下去, 这样下去. 过来 (guòlai) – Rückkehr in den normalen Zustand: 醒过来, 明白过来, 改过来. 过去 (guòqu) – Verlust des normalen Zustands, vor allem des Bewusstseins: 晕过去, 昏过去 (hūn guoqu). Typischer Fehler: 安静起来 oder 冷静起来 statt 安静下来/冷静下来.",
