    "explanation": "Das Zustandskomplement nach 得 (de) ist hier eine Verbalphrase: Sie zeigt das Ausmaß eines Zustands an dem, was jemand deshalb tut oder nicht mehr kann: 高兴得跳了起来 „vor Freude in die Luft springen“, 累得走不动了 „so müde, dass man nicht mehr gehen kann“, 笑得说不出话来 „vor Lachen kein Wort herausbringen“. Die Verbalphrase enthält oft 了, ein Richtungskomplement wie 起来 (qǐlai) oder ein verneintes Potentialkomplement wie 走不动, 说不出 (shuō bu chū). Vor 得 stehen meist Adjektive oder Verben der Gefühle und Zustände wie 高兴 (gāoxìng), 累, 急, 笑 oder 哭. Anders als beim HSK-2-Muster (跑得很快) wird nicht bewertet, sondern eine Folge geschildert.",
