    "explanation": "Hier ist das Komplement nach 得 (de) ein ganzer kleiner Satz mit eigenem Subjekt: Er zeigt, welche Folge die Handlung oder der Zustand für jemand anderen oder für einen Körperteil hat. 冻得手都红了 „so kalt, dass die Hände ganz rot waren“, 吵得我睡不着 „so laut, dass ich nicht schlafen kann“, 讲得大家都笑了 „so erzählt, dass alle lachten“. Im Komplement stehen oft 都, 直 oder ein verneintes Potentialkomplement. Hat das Hauptverb ein Objekt, wird das Verb wiederholt (他讲故事讲得……). Typisch für lebhafte Schilderungen in Erzählung und Gespräch.",
