    "explanation": "Nach 得 (de) steht hier eine feste Wendung, meist ein vierteiliger Chengyu oder eine bildhafte Redensart, die den Zustand anschaulich beschreibt: 忙得团团转 (máng de tuántuánzhuàn) „rotieren vor Arbeit“, 吃得津津有味 (chī de jīnjīn yǒuwèi) „mit großem Genuss essen“, 跑得上气不接下气 (pǎo de shàngqì bù jiē xiàqì) „bis man völlig außer Atem ist“, 说得头头是道 (shuō de tóutóu shìdào) „schlüssig und überzeugend reden“. Jede Wendung passt nur zu bestimmten Verben oder Adjektiven, deshalb lernt man sie am besten als Ganzes mit dem Verb. Vor der Wendung steht kein 很; sie wird auch nicht verneint. Häufig in lebhaften Erzählungen, gesprochen wie geschrieben.",
