    "explanation": "便 (biàn) ist die schriftsprachliche Entsprechung von 就 (jiù). Im 承接复句 (chéngjiē fùjù), dem Satzgefüge der Abfolge, verbindet es zwei Handlungen, die direkt aufeinander folgen: Ist das Erste geschehen, tritt gleich darauf das Zweite ein – „dann, daraufhin, sogleich“. 便 ist ein Adverb: Es steht nach dem Subjekt direkt vor dem Verb, nicht vor dem Subjekt (她便哭了起来, nicht *便她哭了起来). Im ersten Teil markieren oft 了, 后, 完 oder 过 den Abschluss der ersten Handlung. 便 klingt gehoben und erzählend und ist typisch für geschriebene Texte; im Gespräch sagt man 就.",
