    "formation": "一旦 + Ereignis，(Subjekt +) 就 + Folge",
    "notes": "万一 (wànyī) „falls (wider Erwarten)“ betont dagegen die geringe Wahrscheinlichkeit eines Risikos. In der Schriftsprache ist 一旦 (yídàn) auch ein Nomen „ein einziger Tag“: 毁于一旦 (huǐ yú yídàn) „an einem Tag zunichtegemacht werden“. Das Adverb 一旦 ohne 就 ist ein eigener Punkt (HSK 5).",
    "explanation": "一旦 (yídàn) heißt „sobald einmal, wenn erst einmal“. Der erste Teil nennt ein Ereignis, das noch nicht eingetreten oder ungewiss ist; der zweite Teil mit 就 (jiù) beschreibt die Folge, die dann unweigerlich eintritt. Oft geht es um etwas Wichtiges oder Unerwünschtes, dessen Folgen sich schwer rückgängig machen lassen: 一旦失去信任，就很难再恢复 „ist das Vertrauen erst einmal verloren, lässt es sich kaum wiederherstellen“. 一旦 kann vor oder nach dem Subjekt stehen (一旦他知道了 / 他一旦知道了). Das Muster ist neutral bis gehoben. Anders als 如果 (rúguǒ) betont 一旦 nicht die bloße Annahme, sondern den Moment, in dem etwas eintritt, und die Tragweite der Folge.",
