    "explanation": "假如 (jiǎrú) heißt „wenn, falls, angenommen“ und leitet eine Annahme ein; der zweite Teil nennt die Folge, oft mit 就 (jiù). 就 kann fehlen, besonders wenn der zweite Teil ein eigenes Subjekt oder ein Modalverb hat (假如我是你，我会……). 假如 klingt gehobener als 如果 (rúguǒ) und 要是 (yàoshi) und ist vor allem schriftlich. Es eignet sich gut für rein gedachte oder irreale Fälle („wenn ich du wäre“, „angenommen, es gäbe kein …“), kann aber auch reale Bedingungen einleiten. Das Verb verändert sich dabei nicht; ob ein Fall real oder irreal ist, ergibt sich aus dem Zusammenhang. Im Deutschen steht dann oft der Konjunktiv.",
