    "formation": "Aufforderung/Feststellung，要不然/不然 + (unerwünschte) Folge",
    "notes": "要不然 (yàobùrán) oder kurz 要不 (yàobù) kann auch eine Alternative vorschlagen: 要不然我们明天再去吧 „oder (wie wär's), wir gehen morgen“. Mit 幸亏 (xìngkuī) oder 幸好 (xìnghǎo) im ersten Teil heißt es „zum Glück …, sonst wäre …“ (HSK 7–9).",
    "explanation": "要不然 (yàobùrán) und das kürzere 不然 (bùrán) leiten ein, was passiert, wenn das im ersten Teil Gesagte nicht geschieht: „sonst, andernfalls“. Der erste Teil ist oft eine Aufforderung, ein Rat oder eine Notwendigkeit (快点儿走, 你应该……, 我们得……); der zweite Teil nennt die meist unangenehme Folge, häufig mit 就, 会 oder 可能 (kěnéng). Beide Formen sind umgangssprachlich und bedeuten dasselbe wie das gehobenere 否则 (fǒuzé). 要不然/不然 bezieht sich immer auf etwas zuvor Gesagtes und steht am Anfang des zweiten Teils; ein Satz kann nicht mit „sonst“ beginnen, ohne dass vorher die Bedingung genannt wurde.",
