    "explanation": "因而 (yīn'ér) leitet die Folge oder das Ergebnis aus einem vorher genannten Grund ein: „daher, folglich, deshalb“. Es entspricht 所以 (suǒyǐ) und 因此 (yīncǐ), ist aber deutlich schriftsprachlich und typisch für Berichte, Aufsätze und Nachrichten. 因而 steht am Anfang des zweiten Teilsatzes oder nach dessen Subjekt (员工的能力因而……). Im ersten Teil kann 由于 (yóuyú) den Grund markieren. 因而 verbindet meist Teilsätze innerhalb eines Satzes; 因此 kann dagegen auch einen neuen Satz oder Absatz einleiten. Im Gespräch wirkt 因而 steif – dort sagt man 所以.",
