    "explanation": "可见 (kějiàn) leitet eine Schlussfolgerung ein, die man aus einer vorher genannten Tatsache zieht: „daran sieht man, also, offenbar“. Die Richtung ist anders als bei 所以 (suǒyǐ): Der erste Teil ist nicht die Ursache, sondern der Beleg; der zweite Teil ist das, was man daraus erschließt – oft gerade die Ursache: 只有三个人通过了，可见题目很难 „nur drei haben bestanden – die Aufgaben waren also offenbar schwer“. 可见 steht am Anfang des zweiten Teils, in der Regel ohne eigenes Subjekt davor. Sehr häufig ist die feste Wendung 由此可见 (yóucǐ kějiàn) „daraus ergibt sich“, die am Ende eines Absatzes zusammenfasst. Das Muster ist neutral bis schriftlich.",
