    "explanation": "哪怕 (nǎpà) heißt „selbst wenn, auch wenn“: Der erste Teil nennt eine Annahme, oft einen extremen oder ungünstigen Fall (nur ein Tag, hundertmal scheitern), der zweite Teil mit 也 (yě) sagt, dass das Ergebnis trotzdem gilt. Damit drückt der Sprecher Entschlossenheit oder Nachdruck aus. 哪怕 bedeutet dasselbe wie 即使 (jíshǐ), wirkt aber lebhafter und etwas umgangssprachlicher; 即使 ist neutraler. Im ersten Teil stehen häufig 再 (哪怕再忙 „wie beschäftigt auch immer“) oder 只 (哪怕只有一天). Typischer Fehler: 但是 (dànshì) statt 也 im zweiten Teil – 哪怕 ist kein „obwohl“, es nennt in der Regel keine Tatsache, sondern eine Annahme.",
