    "notes": "Gehobene Variante mit 非但 (fēidàn) statt 不但 (búdàn): 非但不……，反而 (fǎn'ér) ……. Das Adverb 反而 allein ist ein eigener Punkt (HSK 5). 不但……，而且 (érqiě) …… (HSK 3) steigert dagegen in dieselbe Richtung („nicht nur …, sondern auch“) und betont kein Umschlagen ins Gegenteil.",
